<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ArrowLeft,ArrowUp,BookOpen,Plus,MessageSquare,FileCode2,Sparkles,X,Search,ChevronRight,Download,Pause,Play,RefreshCw,MoreHorizontal,Trash2,Pencil,Bookmark,Check,Layers,Network,Copy,LoaderCircle,Settings,AlignLeft,ArrowUpRight} from 'lucide-vue-next'
import {useStore} from '../store'
import {api,post,type Book,type Chapter,type Conversation,type Message,type Reference,type Estimate,date} from '../api'
import BookCover from '../components/BookCover.vue'
import Markdown from '../components/Markdown.vue'
const route=useRoute(),router=useRouter(),store=useStore()
const bid=computed(()=>String(route.params.id)),book=ref<Book|null>(null),chapters=ref<Chapter[]>([]),conversations=ref<Conversation[]>([]),cid=ref(''),messages=ref<Message[]>([]),input=ref(''),sending=ref(false),status=ref(''),error=ref(''),loading=ref(true),estimate=ref<Estimate|null>(null),actionBusy=ref(false)
const drawer=ref<'chapter'|'source'|'notes'|'search'|'graph'|''>(''),currentChapter=ref<Chapter|null>(null),source=ref<Reference|null>(null),notes=ref<any[]>([]),noteText=ref(''),searchQuery=ref(''),searchKind=ref('book'),searchResults=ref<any[]>([]),searchBusy=ref(false),otherBookIds=ref<string[]>([]),multi=ref(false),rename=ref<Conversation|null>(null),renameText=ref(''),deleteConv=ref<Conversation|null>(null),confirmRegenerate=ref(false),deleteBook=ref(false),scrollEl=ref<HTMLElement|null>(null),category=ref('快速了解'),mobileToc=ref(false),controller: {value:AbortController|null}={value:null}
let timer:ReturnType<typeof setInterval>|undefined
const recommendations=computed(()=>book.value?.questions?.[category.value]||{'快速了解':['这本书最重要的思想是什么？','帮我概括全书内容。'],'深入理解':['哪些章节之间存在联系？','作者有哪些反直觉观点？'],'实际应用':['把这本书转化成每日 Checklist。','帮我制定一个 30 天实践计划。'],'批判阅读':['作者的论证有什么局限？','哪些观点缺乏证据？']}[category.value]||[])
async function load(){loading.value=true;error.value='';try{book.value=await api('/books/'+bid.value);chapters.value=await api('/books/'+bid.value+'/chapters');conversations.value=await api('/books/'+bid.value+'/conversations');cid.value=conversations.value[0]?.id||'';if(cid.value)messages.value=await api('/books/'+bid.value+'/conversations/'+cid.value+'/messages');else messages.value=[];estimate.value=await api('/books/'+bid.value+'/estimate')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function refreshBook(){try{book.value=await api('/books/'+bid.value);if(book.value?.status==='ready'&&store.books.find(b=>b.id===bid.value)?.status!=='ready')store.loadBooks()}catch{}}
onMounted(()=>{load();timer=setInterval(()=>{if(book.value?.status==='generating')refreshBook()},2000)})
onUnmounted(()=>{clearInterval(timer);controller.value?.abort()})
watch(bid,()=>{controller.value?.abort();drawer.value='';otherBookIds.value=[];load()})
async function scrollDown(){await nextTick();scrollEl.value?.scrollTo({top:scrollEl.value.scrollHeight,behavior:'smooth'})}
async function newConversation(){if(sending.value)return;try{const c=await post<Conversation>('/books/'+bid.value+'/conversations',{title:'新的对话'});conversations.value.unshift(c);cid.value=c.id;messages.value=[];input.value=''}catch(e){store.notify((e as Error).message)}}
async function selectConversation(c:Conversation){if(sending.value)return;cid.value=c.id;try{messages.value=await api('/books/'+bid.value+'/conversations/'+c.id+'/messages');scrollDown()}catch(e){store.notify((e as Error).message)}}
async function renameConversation(){if(!rename.value||!renameText.value.trim())return;try{await api('/books/'+bid.value+'/conversations/'+rename.value.id,{method:'PATCH',body:JSON.stringify({title:renameText.value.trim()})});conversations.value=await api('/books/'+bid.value+'/conversations');rename.value=null}catch(e){store.notify((e as Error).message)}}
async function removeConversation(){if(!deleteConv.value)return;try{await api('/books/'+bid.value+'/conversations/'+deleteConv.value.id,{method:'DELETE'});if(cid.value===deleteConv.value.id){cid.value='';messages.value=[]}conversations.value=await api('/books/'+bid.value+'/conversations');deleteConv.value=null}catch(e){store.notify((e as Error).message)}}
async function send(question?:string){const q=(question||input.value).trim();if(!q||sending.value)return;if(!store.config.model){store.notify('请先在 AI 设置中配置模型');router.push('/settings?return='+encodeURIComponent(route.path));return}if(!cid.value)await newConversation();if(!cid.value)return;sending.value=true;error.value='';input.value='';messages.value.push({id:'local-'+Date.now(),role:'user',content:q,references:[]});status.value='正在路由相关知识…';scrollDown();controller.value=new AbortController()
 try{const response=await fetch('/api/books/'+bid.value+'/conversations/'+cid.value+'/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,config:store.config,otherBookIds:otherBookIds.value}),signal:controller.value.signal});if(!response.ok){const b=await response.json();throw new Error(b.detail||'问书失败')}if(!response.body)throw new Error('浏览器不支持读取响应流');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const {value,done}=await reader.read();buffer+=decoder.decode(value,{stream:!done});const lines=buffer.split('\n');buffer=lines.pop()||'';for(const line of lines){if(!line)continue;const event=JSON.parse(line);if(event.type==='status')status.value=event.message;if(event.type==='answer'){messages.value.push(event.message);scrollDown()}if(event.type==='error')throw new Error(event.message)}if(done)break}conversations.value=await api('/books/'+bid.value+'/conversations')}
 catch(e){error.value=(e as Error).name==='AbortError'?'已停止本次回答。':(e as Error).message}finally{sending.value=false;status.value='';controller.value=null}}
async function generate(reset=false){if(!store.config.model){router.push('/settings?return='+encodeURIComponent(route.path));return}actionBusy.value=true;error.value='';try{await post('/books/'+bid.value+'/generate',{config:store.config,reset,purpose:book.value?.metadata?.purpose||'all'});confirmRegenerate.value=false;await refreshBook()}catch(e){error.value=(e as Error).message}finally{actionBusy.value=false}}
async function pause(){try{await post('/books/'+bid.value+'/pause');refreshBook()}catch(e){error.value=(e as Error).message}}
async function openChapter(id:string,bookId=bid.value){try{currentChapter.value=await api('/books/'+bookId+'/chapters/'+id);drawer.value='chapter';mobileToc.value=false}catch(e){store.notify((e as Error).message)}}
function openSource(r:Reference){source.value=r;drawer.value='source'}
async function openNotes(){drawer.value='notes';notes.value=await api('/books/'+bid.value+'/notes')}
async function saveNote(text=noteText.value){if(!text.trim())return;try{await post('/books/'+bid.value+'/notes',{content:text});noteText.value='';notes.value=await api('/books/'+bid.value+'/notes');store.notify('已保存到读书笔记')}catch(e){store.notify((e as Error).message)}}
async function removeNote(nid:string){await api('/books/'+bid.value+'/notes/'+nid,{method:'DELETE'});notes.value=await api('/books/'+bid.value+'/notes')}
async function search(){if(!searchQuery.value.trim())return;searchBusy.value=true;try{searchResults.value=await api('/books/'+bid.value+'/search?q='+encodeURIComponent(searchQuery.value)+'&kind='+searchKind.value)}catch(e){store.notify((e as Error).message)}finally{searchBusy.value=false}}
async function copy(text:string){try{await navigator.clipboard.writeText(text);store.notify('已复制')}catch{store.notify('浏览器不允许剪贴板访问')}}
async function removeBook(){actionBusy.value=true;try{await api('/books/'+bid.value,{method:'DELETE'});await store.loadBooks();router.push('/')}catch(e){store.notify((e as Error).message)}finally{actionBusy.value=false}}
const graphNodes=computed(()=>chapters.value.map((ch,i)=>({x:190+Math.cos(i*2*Math.PI/Math.max(chapters.value.length,1))*145,y:180+Math.sin(i*2*Math.PI/Math.max(chapters.value.length,1))*125,ch})))
</script>
<template><div v-if="loading" class="loading-block"><LoaderCircle class="spin" :size="25"/>正在打开这本书…</div><div v-else-if="!book" class="page"><div class="error-box">{{error}}</div><RouterLink to="/" class="button">返回书架</RouterLink></div><div v-else class="book-workspace">
 <header class="book-toolbar"><RouterLink to="/" class="back-link"><ArrowLeft :size="16"/><span>书架</span></RouterLink><div class="toolbar-book-name">{{book.title}}</div><div class="toolbar-actions"><button class="icon-button mobile-only" @click="mobileToc=!mobileToc" aria-label="打开目录"><AlignLeft :size="18"/></button><button class="button small-button" @click="openNotes" aria-label="读书笔记"><Bookmark :size="15"/><span>笔记</span></button><RouterLink :to="'/books/'+bid+'/skill'" class="button small-button" aria-label="查看 Skill"><FileCode2 :size="15"/><span>查看 Skill</span></RouterLink><a v-if="book.metadata" :href="'/api/books/'+bid+'/export'" class="icon-button" title="导出 Skill"><Download :size="17"/></a><button class="icon-button danger" title="删除书籍" @click="deleteBook=true"><Trash2 :size="16"/></button></div></header>
 <div class="book-layout"><aside class="book-sidebar" :class="{'mobile-open':mobileToc}"><div class="book-sidebar-summary"><BookCover :book="book" small/><div><h3>{{book.title}}</h3><p>{{book.author}}</p><span class="status-badge" :class="book.status"><span></span>{{book.status==='ready'?'Skill 已加载':book.status==='generating'?'正在生成':'等待转换'}}</span></div></div><div class="book-sidebar-links"><button @click="drawer='search'"><Search :size="15"/>搜索知识与原文</button><button @click="drawer='graph'"><Network :size="15"/>章节探索</button></div><div class="section-label">目录<span>{{chapters.length}} 章</span></div><div class="chapter-list"><button v-for="(ch,i) in chapters" :key="ch.id" @click="openChapter(ch.id)"><span>{{String(i+1).padStart(2,'0')}}</span><div>{{ch.title}}</div><ChevronRight :size="13"/></button><p v-if="!chapters.length" class="hint">此 Skill 未包含原文章节</p></div><div class="section-label conversation-label">问书记录<button class="icon-button" :disabled="sending" @click="newConversation" title="新建对话"><Plus :size="15"/></button></div><div class="conversation-list"><div v-for="c in conversations" :key="c.id" class="conversation-item" :class="{selected:cid===c.id}"><button :disabled="sending" @click="selectConversation(c)"><MessageSquare :size="14"/><span>{{c.title}}</span></button><button class="icon-button conversation-action" :disabled="sending" @click="rename=c;renameText=c.title" title="重命名对话"><Pencil :size="12"/></button><button class="icon-button conversation-action" :disabled="sending" @click="deleteConv=c" title="删除对话"><X :size="13"/></button></div><p v-if="!conversations.length" class="hint">开始提问后，会保存到这里。</p></div></aside>
 <section v-if="book.status!=='ready'" class="generation-pane"><div class="generation-inner"><div class="generation-emblem"><Sparkles :size="34" :stroke-width="1.2"/></div><div class="eyebrow">BOOK → KNOWLEDGE → SKILL</div><h2>{{book.status==='generating'?'正在把这本书变成 Skill':book.status==='failed'?'让知识继续生长':book.status==='paused'?'已为你保留分析进度':'这本书，准备好被理解了'}}</h2><p>{{book.stage}}</p><div class="progress-track"><i :style="{width:book.progress+'%'}"/></div><div class="progress-caption"><span>{{book.status==='generating'?'AI 正在分析书籍，请保持本地服务运行':'每个章节都独立保存，支持断点恢复'}}</span><strong>{{book.progress}}%</strong></div><div class="generation-steps"><div><Check :size="16"/>读取电子书</div><div><Check :size="16"/>识别 {{book.chapterCount}} 个章节</div><div :class="{pending:book.progress<75}"><Check v-if="book.progress>=75" :size="16"/><LoaderCircle v-else-if="book.status==='generating'" class="spin" :size="16"/><span v-else class="step-dot"></span>分析章节与知识结构</div><div :class="{pending:book.progress<90}"><Check v-if="book.progress>=90" :size="16"/><span v-else class="step-dot"></span>生成 Book Skill</div><div class="pending"><span class="step-dot"></span>构建原文索引</div></div><div class="discovered" v-if="book.stats.concepts"><span>已发现的知识</span><strong>{{book.stats.concepts}} 个概念 · {{book.stats.methods||0}} 个方法</strong></div><div v-if="book.error||error" class="error-box">{{book.error||error}}<RouterLink to="/settings" class="text-link">打开 AI 设置</RouterLink></div><div v-if="book.status!=='generating'" class="generation-estimate">约 {{estimate?.tokens.toLocaleString()}} 输入 Tokens · {{estimate?.requests}} 次请求（估算）<small v-if="estimate?.checkpoints">已有 {{estimate.checkpoints}} 个分析检查点可复用</small></div><button v-if="book.status==='generating'" class="button" @click="pause"><Pause :size="16"/>暂停生成</button><button v-else class="button primary" :disabled="actionBusy" @click="generate()"><Play :size="16"/>{{book.status==='parsed'?'开始生成 Skill':'继续生成'}}</button></div></section>
 <section v-else class="chat-pane"><div ref="scrollEl" class="chat-scroll"><div v-if="!messages.length" class="chat-welcome"><div class="chat-emblem"><BookOpen :size="30" :stroke-width="1.3"/><span class="spark-badge"><Sparkles :size="13"/></span></div><div class="eyebrow">A CONVERSATION WITH KNOWLEDGE</div><h2>与《{{book.title.replace(' · 功能示例','')}}》<br/>开启一场新的对话</h2><p>从一个好问题开始，走进观点背后的思考。</p><div class="question-tabs"><button v-for="cat in ['快速了解','深入理解','实际应用','批判阅读']" :key="cat" :class="{selected:category===cat}" @click="category=cat">{{cat}}</button></div><div class="recommended-questions"><button v-for="q in recommendations.slice(0,4)" :key="q" @click="send(q)"><Sparkles :size="14"/><span>{{q}}</span><ArrowUpRight :size="15"/></button></div><div class="action-prompts"><button @click="send('根据本书制作 10 张问答式 Flashcards，每张卡片包括问题、答案和相关章节。')">Flashcards</button><button @click="send('根据本书设计 5 道测验题，先只展示问题，等我回答后评分并引用原文解释。')">阅读测验</button><button @click="send('根据本书制定一个循序渐进的学习计划，注明章节、练习和每日行动。')">学习计划</button></div></div>
 <div v-else class="message-list"><article v-for="m in messages" :key="m.id" class="chat-message" :class="m.role"><div class="message-heading"><span class="message-avatar"><BookOpen v-if="m.role==='assistant'" :size="15"/><span v-else>我</span></span><strong>{{m.role==='assistant'?'问书':'你'}}</strong><span v-if="m.role==='assistant'" class="message-skill-label">基于 Book Skill</span></div><Markdown :text="m.content"/><div v-if="m.references?.length" class="sources"><div class="sources-label"><BookOpen :size="14"/>来自本书 · 可追溯的依据</div><button v-for="r in m.references" :key="r.id" @click="openSource(r)"><span>[{{r.citation}}]</span>{{otherBookIds.length?r.bookTitle+' · ':''}}{{r.chapter}}<ArrowUpRight :size="13"/></button></div><div v-if="m.role==='assistant'" class="message-actions"><button @click="copy(m.content)"><Copy :size="13"/>复制</button><button @click="saveNote(m.content)"><Bookmark :size="13"/>存为笔记</button></div></article></div><div v-if="sending" class="agent-status"><LoaderCircle class="spin" :size="17"/>{{status}}</div><div v-if="error" class="error-box chat-error">{{error}}<RouterLink to="/settings" class="text-link">检查 AI 设置</RouterLink><button class="text-link" v-if="messages.at(-1)?.role==='user'&&!sending" @click="send(messages.at(-1)?.content)">重试问题</button></div></div>
 <div class="composer-wrap"><div v-if="multi" class="multi-picker"><strong>联合问书 <small>最多 5 本</small></strong><label v-for="b in store.books.filter(b=>b.status==='ready'&&b.id!==bid)" :key="b.id"><input type="checkbox" :value="b.id" v-model="otherBookIds" :disabled="!otherBookIds.includes(b.id)&&otherBookIds.length>=4"/>{{b.title}}</label><p v-if="!store.books.some(b=>b.status==='ready'&&b.id!==bid)" class="hint">添加并转换更多书籍后，就可以比较不同作者的观点。</p></div><div class="composer"><textarea v-model="input" placeholder="问这本书任何问题…" rows="2" :disabled="sending" aria-label="输入问题" @keydown.enter.exact.prevent="send()" @keydown.enter.shift.exact.stop/><div class="composer-footer"><button class="composer-skill" @click="multi=!multi"><Layers :size="14"/>{{otherBookIds.length?'已选择 '+(otherBookIds.length+1)+' 本书':'Book Skill 已加载'}}<ChevronRight :size="12"/></button><div><span class="composer-hint">Enter 发送 · Shift + Enter 换行</span><button v-if="sending" class="send-button" @click="controller.value?.abort()" aria-label="停止回答"><Pause :size="17"/></button><button v-else class="send-button" :disabled="!input.trim()" @click="send()" aria-label="发送问题"><ArrowUp :size="19"/></button></div></div></div><div class="composer-disclaimer">以书为据，独立思考。AI 的分析和补充知识会单独标记。</div></div></section>
 </div></div>
 <div v-if="drawer" class="drawer-overlay" @click.self="drawer=''"><aside class="reader-drawer"><header><h3>{{drawer==='chapter'?'章节原文':drawer==='source'?'原文证据':drawer==='notes'?'读书笔记':drawer==='graph'?'章节探索':'搜索知识与原文'}}</h3><button class="icon-button" @click="drawer=''" aria-label="关闭面板"><X :size="20"/></button></header><div class="drawer-body"><template v-if="drawer==='chapter'&&currentChapter"><div class="eyebrow">ORIGINAL TEXT</div><h2>{{currentChapter.title}}</h2><div class="chapter-original">{{currentChapter.content}}</div></template><template v-if="drawer==='source'&&source"><div class="eyebrow">SOURCE [{{source.citation}}]</div><h2>{{source.chapter}}</h2><p class="hint">{{source.bookTitle}} · 第 {{source.paragraph}} 段 · 字符 {{source.start}}–{{source.end}}</p><blockquote class="source-quote">{{source.text}}</blockquote><button class="button" @click="openChapter(source.chapterId,source.bookId)">打开完整章节<ArrowUpRight :size="15"/></button></template><template v-if="drawer==='notes'"><p class="hint">记录此刻的想法，也可以将问书回答直接保存到这里。</p><textarea class="note-input" v-model="noteText" placeholder="今天，从这本书里学到了什么？" rows="5"/><button class="button primary" :disabled="!noteText.trim()" @click="saveNote()"><Bookmark :size="15"/>保存笔记</button><article v-for="n in notes" :key="n.id" class="note-card"><div><span>{{date(n.createdAt)}}</span><button class="icon-button" @click="removeNote(n.id)" title="删除笔记"><Trash2 :size="14"/></button></div><Markdown :text="n.content"/></article><p v-if="!notes.length" class="hint">还没有笔记。好的理解，值得留下来。</p></template><template v-if="drawer==='search'"><div class="segmented"><button :class="{selected:searchKind==='book'}" @click="searchKind='book';searchResults=[]">原文搜索</button><button :class="{selected:searchKind==='skill'}" @click="searchKind='skill';searchResults=[]">Skill 搜索</button></div><form class="search-form" @submit.prevent="search"><input v-model="searchQuery" placeholder="输入概念、人物或关键词…"/><button class="button primary" :disabled="searchBusy"><Search :size="16"/></button></form><p class="hint">BM25 全文检索 · {{searchResults.length}} 个结果</p><button v-for="r in searchResults" :key="r.id" class="search-result" @click="searchKind==='book'?openChapter(r.chapterId):router.push('/books/'+bid+'/skill?file='+encodeURIComponent(r.path))"><strong>{{r.chapter||r.path}}</strong><p>{{(r.text||r.content).slice(0,240)}}…</p><ArrowUpRight :size="14"/></button></template><template v-if="drawer==='graph'"><div class="eyebrow">EXPLORE THE STRUCTURE</div><h2>从全书，走进每一章</h2><p class="hint">展示全书的章节结构。点击节点查看原文；跨章节概念关系可在 Skill 的 connections / relationships 文件中阅读。</p><svg class="chapter-graph" viewBox="0 0 380 360"><line v-for="n in graphNodes" :key="'line'+n.ch.id" x1="190" y1="180" :x2="n.x" :y2="n.y" stroke="#c8d1c7"/><circle cx="190" cy="180" r="37" fill="#284c3e"/><text x="190" y="184" text-anchor="middle" fill="white" font-size="13">Book Skill</text><g v-for="(n,i) in graphNodes" :key="n.ch.id" class="graph-node" @click="openChapter(n.ch.id)" tabindex="0" @keydown.enter="openChapter(n.ch.id)"><circle :cx="n.x" :cy="n.y" r="24" fill="#edf1e9" stroke="#becdbd"/><text :x="n.x" :y="n.y+4" text-anchor="middle" font-size="12">{{i+1}}</text></g></svg><button v-for="(ch,i) in chapters" :key="ch.id" class="graph-chapter" @click="openChapter(ch.id)"><span>{{String(i+1).padStart(2,'0')}}</span>{{ch.title}}<ChevronRight :size="14"/></button></template></div></aside></div>
 <div v-if="rename||deleteConv||deleteBook||confirmRegenerate" class="modal-backdrop"><div class="modal"><template v-if="rename"><h2>重命名对话</h2><input v-model="renameText" maxlength="200" @keydown.enter="renameConversation"/><div class="modal-actions"><button class="button" @click="rename=null">取消</button><button class="button primary" @click="renameConversation">保存</button></div></template><template v-else-if="deleteConv"><h2>删除这段对话？</h2><p>《{{deleteConv.title}}》中的所有消息将永久删除。</p><div class="modal-actions"><button class="button" @click="deleteConv=null">取消</button><button class="button danger-button" @click="removeConversation">删除</button></div></template><template v-else-if="deleteBook"><h2>删除《{{book?.title}}》？</h2><p>原始电子书、Skill、索引、笔记和所有对话都会被删除，无法恢复。</p><div class="modal-actions"><button class="button" @click="deleteBook=false">取消</button><button class="button danger-button" :disabled="actionBusy" @click="removeBook">确认删除</button></div></template></div></div>
</template>
